.Super-Menu-logo{display:none}
#top-bar .container{background:var(--top-bar);padding:6px 0px;margin-bottom:8px;border-radius: 4px 4px 0 0;box-shadow: 0 -2px 5px 1px rgb(0 0 0 / 0.07);}
#top-menu .selectnav{display:none}
.date-format{position:relative;color:var(--button-bg-color);font-weight:600;text-align:center;gap:4px;display:flex;vertical-align:middle;padding:0 10px;align-items:center;}
.date-format:before{content:'\f133';font-family:'Font Awesome 6 Free';position:relative;}
.header-room{display:flex;flex-wrap:wrap;flex-direction:row;justify-content:space-between;align-items:center;align-content:center;}
.header-room .social li{display:inline-block;list-style:none;line-height:40px}
.header-room .social li a{display:block;width:25px;line-height:30px;margin: 0 7px;font-size:15px;text-align:center;color:var(--top-menu-text)}
.dark .post-body ol>li:before{color:#eee}
.ticker-pro .loading-icon{line-height:38px;}
.ticker-pro .widget .widget-content .error-status{padding:0;line-height:30px;}
.ticker-pro .loading-icon:after{width:20px;height:20px;}
.ticker{position:relative;float:left;width:100%;margin:0;}
.ticker-pro{position:relative;margin:5px 10px 15px;overflow:hidden;background:var(--bg-cards);border-radius: 4px;box-shadow:var(--bg-cards-shadow);}
.ticker-pro .widget{display:block;height:30px;padding:5px 0;margin:0}
.ticker-pro .widget>.widget-title{display:block;position:relative;float:left;height:25px;line-height:25px;padding:0 10px;margin:0 10px 0 5px;border-right:1px solid rgba(0 0 0 / 0.18)}
.ticker-pro .widget>.widget-title>h3{display: flex;align-items: center;font-size:14px;font-weight:700;color:var(--theme-text-color);line-height:30px;margin:0;gap:5px}
.ticker-pro .widget>.widget-title>h3:before{content:'\f0e7';font-family:'Font Awesome 6 Free';float:left;font-size:9px;font-weight:900;margin:0;text-align:center;width:16px;height:16px;border-radius:50%;background:var(--button-bg-color);color:var(--button-text-color);line-height:17px;}
.ticker-pro .widget-content{position:relative;justify-content:flex-end;flex:1;align-items:center;margin:0 10px;display:none;height:30px;overflow:hidden;}
.breaking-ticker{position:relative;display:flex;box-sizing:border-box;justify-content:space-between;flex:1;margin:0;height:30px;}
.ticker-pro .open-iki,.ticker-pro .widget.PopularPosts .widget-content{display:flex!important}
.breaking-ticker .tickerNews .entry-title{height:30px;font-size:13px;font-weight:600;line-height:30px;margin:0;padding:0;overflow:hidden}
.breaking-ticker .tickerNews .entry-title a{position:relative;display:block;overflow:hidden;font-size:13px;}
.rtl .ticker-pro .widget>.widget-title{float: right;border-left: 1px solid rgba(0 0 0 / 0.18);border-right: unset;}
.breaking-ticker .active, .AflexNewsTested .active{opacity:1;visibility:visible;transform:translate3d(0,0,0);pointer-events:initial}
.mega-flex .section{width:50%;}
.tickerNews, .tickerPart{position:absolute;top:0;left:0;opacity:0;visibility:hidden;pointer-events:none;}
.rtl .tickerNews,.rtl .tickerPart{right: 0;}
.tickerPart{width: 100%;}
.tickerPart{transform:translate3d(80px,0,0);transition:all .80s cubic-bezier(0.68, -0.55, 0.27, 1.55)}
.tickerNews{transform:translate3d(10px,0,0);transition:all .80s ease}
.buttons-fix{display:flex;flex-direction:row;align-items:center;justify-content:space-around;margin:0;gap: 8px;height:30px}
.buttons-fix>a{display:flex;width:20px;height:20px;line-height:20px;font-size:12px;text-align:center;margin:0 2px;padding:5px;cursor:pointer;color:var(--bt-breaking-text);background:var(--bt-breaking)}
.buttons-fix>a:hover{opacity:0.8;}
.buttons-fix .prev:before{content:'\f053'}
.buttons-fix .next:before{content:'\f054'}
.buttons-fix a:before{display:block;font-family:'Font Awesome 6 Free';margin:auto;text-align:center;font-weight:900}
.mega-mode{position:relative;padding:0 15px;margin-right:10px;text-align:center;border-radius:30px;display:inline-block;align-items:center;z-index:999}
.dark-button{display:none;}
.dark-button + .dark-toggle{outline:0;display:inline-block;width:40px;height:20px;vertical-align:middle;position:relative;cursor:pointer;margin-left:5px;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none;}
.dark-mode + .dark-toggle{border-radius:99em;transition:all .4s ease}
.dark-mode + .dark-toggle:after{content:'\f185';font-family:'Font Awesome 6 Free';font-size: 10px;font-weight:900;color:var(--button-text-color);line-height:18px;border-radius:100px;background:var(--button-bg-color);transition:left 0.3s cubic-bezier(0.175,0.885,0.32,1.275),padding 0.3s ease,margin 0.3s ease;position:absolute;width:18px;height:18px;top:1px;left:2px;box-shadow:0 3px 6px rgba(0,0,0,0.16),0 3px 6px rgba(0,0,0,0.23)}
.dark .dark-mode + .dark-toggle{background:rgb(255 237 198 / 0.41)}
.dark-mode + .dark-toggle{background:rgb(111 111 111 / 0.25)}
.dark .dark-mode + .dark-toggle:after{content:'\f186';left:53%;background:#d5904e}
#Super-FlexMenuList>.mega-menu{position:unset!important}
.Super-FlexMenu li:hover .BiggerMenu{opacity:1;visibility:visible}
.drop-down>a:after{content:'\f078';float:right;font-family:'Font Awesome 6 Free';font-size:9px;font-weight:900;margin:-1px 0 0 5px}
.BiggerMenu{position:absolute;background-color:var(--block-bg);top:59px;opacity:0;visibility:hidden;width:100%;left:0;box-sizing:border-box;border-radius:4px;right:0;z-index:3333;color:var(--white-bg);height:auto;padding:20px;min-height:100px;box-shadow:0 10px 10px rgba(0,0,0,0.28);transition:all .3s ease;}
.Super-FlexMenu li:hover .BiggerMenu{margin-top:1px;opacity:1;visibility:visible}
.mega-box{width:calc((100% - 50px) / 5);box-sizing:border-box;float:left;overflow:hidden;position:relative}
.mega-box:last-child{margin-right:0}
.mega-box .post-filter-link{position:relative;height:100%}
.mega-boxs{display:flex;justify-content:space-between;flex-wrap:wrap}
.mega-boxs .Mega-img-ui{height:180px;display:block;overflow:hidden;border-radius: 4px;}
.mega-boxs .entry-title{font-size:14px;font-weight:600;text-align: left;line-height:1.5;margin:0}
.flex-section{display:flex;flex-wrap: wrap;width:100%;float:left;align-items:center;justify-content:center;}
.flex-ft{display:flex;justify-content:center;padding: 0 10px;}
.tociki-pro{display:flex;width:100%;clear:both;margin:0}
.tociki-inner{position:relative;max-width:100%;font-size:14px;background-color:rgba(165 165 165 / 0.10);overflow:hidden;line-height:23px;border:1px solid #a0a0a0;border-radius:5px}
a.tociki-title{position:relative;display:flex;align-items:center;justify-content:space-between;height:38px;font-size:16px;font-weight:600;color:var(--text-font-color);padding:0 15px;margin:0}
.tociki-title-text{display:flex}
.tociki-title-text:before{content:'\f0cb';font-family:'Font Awesome 6 Free';font-size:14px;font-weight:900;margin:0 5px 0 0}
.rtl .tociki-title-text:before{margin:0 0 0 5px}
.tociki-title:after{content:'\f078';font-family:'Font Awesome 6 Free';font-size:12px;font-weight:900;margin:0 0 0 25px;color:var(--buttons-category-text);}
.rtl .tociki-title:after{margin:0 25px 0 0;}
.tociki-title.opened:after{content:'\f077'}
a.tociki-title:hover{text-decoration:none}
#tociki{display:none;padding:0 15px 10px;margin:0}
#tociki ol{padding:0 0 0 15px}
