.Super-MenuWorks.fixed-nos.show{background:var(--main-menu-bg)}
.main-menu-wrap{position:static;height:56px;margin:0}
#Super-FlexMenu .widget,#Super-FlexMenu .widget>.widget-title{display:none}
#Super-FlexMenu .show-menu{display:block}
#Super-FlexMenu{position:static;height:56px;z-index:10}
#Super-FlexMenu ul>li{position:relative;display: flex;flex-shrink: 0;}
#Super-FlexMenuList>li>a{position:relative;display:block;height:56px;font-size:14px;color:var(--main-menu-text-color);font-weight:600;text-transform:capitalize;line-height:56px;padding:0 10px;margin:0}
#Super-FlexMenuList>li>a i{margin:0 3px 0 0;font-size:16px;color:var(--button-bg-color)}
#Super-FlexMenuList>li>a:hover{opacity:0.8}
.rtl #Super-FlexMenu ul>li>ul>li>ul{right: 100%;left: unset;}
.rtl #Super-FlexMenu ul>li>ul{right:0;left: unset;}
#Super-FlexMenu ul>li>ul{position:absolute;float:left;left:0;top:60px;width:180px;background:var(--submenu-bg-color);z-index:99999;visibility:hidden;opacity:0;-webkit-transform:translateY(-10px);transform:translateY(-10px);padding:0;box-shadow:0 2px 5px 0 rgba(0,0,0,0.15),0 2px 10px 0 rgba(0,0,0,0.17)}
#Super-FlexMenu ul>li>ul>li>ul{position:absolute;top:0;left:100%;-webkit-transform:translateX(-10px);transform:translateX(-10px);margin:0}
#Super-FlexMenu ul>li>ul>li{display:block;float:none;position:relative}
#Super-FlexMenu ul>li:not(ul>li>ul>li):nth-child(1) a:before{content:'\f015';font-family:'Font Awesome 6 Free';font-size:15px;font-weight:900;margin:0 7px 0 0;}
#Super-FlexMenu ul>li>ul>li a{position:relative;display:block;overflow:hidden;font-size:13px;color:var(--sub-menu-text-color);font-weight:600;box-sizing:border-box;padding:8px 15px;margin:0;border-bottom:1px solid rgba(155,155,155,0.07)}
#Super-FlexMenu ul>li>ul>li:last-child a{border:0}
#Super-FlexMenu ul>li>ul>li:hover>a{opacity:0.8}
#Super-FlexMenu ul>li.sub-tab>a:after,#Super-FlexMenu ul>li.sub-has>a:after{content:'\f078';float:right;font-family:'Font Awesome 6 Free';font-size:9px;font-weight:900;margin:1px 0 0 5px}
#Super-FlexMenu ul>li>ul>li.sub-tab>a:after{content:'\f054';float:right;}
#Super-FlexMenu ul>li:hover>ul,#Super-FlexMenu ul>li>ul>li:hover>ul{visibility:visible;opacity:1;-webkit-backface-visibility:hidden;backface-visibility:hidden;-webkit-transform:translate(0);transform:translate(0)}
#Super-FlexMenu ul ul{transition:all .35s ease}
.loading-icon{width:100%;height:100%;display:flex ;justify-content:center;align-items:center;}
.raw-box .loading-icon{height:185px}
.loading-icon:after{content:"";width:40px;height:40px;border-radius:50%;border:2px solid var(--main-text-color);border-right:2px solid #c1c1c1;display:inline-block;animation:runload 0.6s infinite}
@-webkit-keyframes runload{0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}}@keyframes runload{0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}}
.loading-frame{-webkit-animation-duration:.5s;animation-duration:.5s;-webkit-animation-fill-mode:both;animation-fill-mode:both}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.run-time{animation-name:fadeIn}
@keyframes fadeInUp{from{opacity:0;transform:translate3d(0,5px,0)}to{opacity:1;transform:translate3d(0,0,0)}}
.load-time{animation-name:fadeInUp}
.overlay{visibility:hidden;opacity:0;position:fixed;top:0;left:0;right:0;bottom:0;z-index:1000;margin:0;transition:all .25s ease}
.show-menu-space:before{content:"\f0c9";font-family:'Font Awesome 6 Free';font-size:20px;font-weight:900}
#menu-space{display:none;position:fixed;width:70%;height:100%;top:0;left:0;bottom:0;background:var(--mobile-menu-bg);overflow:auto;z-index:1010;left:0;-webkit-transform:translateX(-100%);transform:translateX(-100%);visibility:hidden;box-shadow:3px 0 7px rgba(0,0,0,0.1);-webkit-transition:all .5s cubic-bezier(.79,.14,.15,.86);-moz-transition:all .5s cubic-bezier(.79,.14,.15,.86);-o-transition:all .5s cubic-bezier(.79,.14,.15,.86);transition:all .5s cubic-bezier(.79,.14,.15,.86)}
.spring-open #menu-space{-webkit-transform:translateX(0);transform:translateX(0);visibility:visible;opacity:.99;-webkit-transition:all .5s cubic-bezier(.79,.14,.15,.86);-moz-transition:all .5s cubic-bezier(.79,.14,.15,.86);-o-transition:all .5s cubic-bezier(.79,.14,.15,.86);transition:all .5s cubic-bezier(.79,.14,.15,.86)}
.area-runs{display:flex;padding:10px;box-shadow:3px 2px 4px 1px rgb(86 86 86 / 6%);justify-content:space-between;opacity:0;transition:all ease-in-out .3s;}
#menu-space{transition:all .6s ease-in-out}
.hide-Super-Menu:hover{opacity:0.8;}
.hide-Super-Menu{display:block;color:var(--main-menu-text-color);font-size:14px;line-height:28px;text-align:center;cursor:pointer;z-index:20;background:rgb(137 137 137 / 0.10);border-radius:4px;padding:0 12px;transition:transform ease-out .2s;}
.hide-Super-Menu:before{content:"\f00d";font-family:'Font Awesome 6 Free';font-weight:900}
.spring-open .area-runs,.spring-open .menu-space-flex{opacity:1}
.menu-space-flex{display:flex;flex-direction:column;opacity:0;justify-content:space-between;float:left;width:100%;height:calc(100% - 8%);transition:all ease-in-out .3s}
.social-mobile ul{margin: 0 0 0 15px;float: left;}
.post-inner-data.flex{display:flex;align-content:center;}
.post-inner-user{position:relative;float:left;}
.author-image{position:relative;display:block;height:40px;width:40px;}
.author-image img{border-radius:50%;}
.Super-Menu{position:relative;float:left;width:100%;box-sizing:border-box;padding:15px}
ul#Super-FlexMenuList{display:flex;height:56px;margin: 0 0 0 15px;}
.Super-Menu>ul{margin:0}
#Super-FlexMenu .fa{padding:0 5px}
.Super-Menu .fa{margin:5px;padding:auto}
.Super-Menu .m-sub{display:none;padding:0}
.Super-Menu ul li{position:relative;display:block;overflow:hidden;float:left;width:100%;font-size:14px;font-weight:600;margin:0;padding:0}
.Super-Menu>ul li ul{overflow:hidden}
.Super-Menu>ul>li{border-bottom:1px solid rgb(181 181 181 / 0.20)}
.Super-Menu>ul>li.sub-tab>a:after,.Super-Menu>ul>li>ul>li.sub-tab>a:after{font-family:'Font Awesome 6 Free';font-weight:900;content:"\f078";font-size:12px;position:absolute;right:0;margin-right:10px;height:100%;flex-direction:row;align-items:center;justify-content:center}
.rtl .Super-Menu>ul>li.sub-tab>a:after,.rtl .Super-Menu>ul>li>ul>li.sub-tab>a:after{left:0;right:unset;}
.Super-Menu ul li.sub-tab.show>a:after{content:'\f077'}
.Super-Menu ul li a:hover,.Super-Menu ul li.sub-tab.show>a,.Super-Menu ul li.sub-tab.show>.submenu-toggle{color:fff}
.Super-Menu>ul>li>ul>li a{display:block;font-size:13px;font-weight:600;color:var(--sub-menu-text-color);padding:5px 0 5px 15px;}
.Super-Menu>ul>li>ul>li a:before{content:"\2022";font-family:'Font Awesome 6 Free';font-style:normal;font-weight:700;color:rgb(88 88 88 / 0.42);font-size:15px;padding-right:5px}
.Super-Menu>ul>li>ul>li>ul>li>a{padding:5px 0 5px 30px}
.Super-Menu ul>li>.submenu-toggle:hover{opacity:0.8;}
.fixed-nos{position:fixed;top:-80px;left:0;width:100%;z-index:990;box-shadow: none;transition:top .17s ease}
.spring-open .fixed-nos{top:0}
.spring-open{overflow:hidden;left:0;right:0}
.search-wrap{position:relative;display:flex;height:56px;align-items:center;margin:0;}
#search-flex{display:none;position:absolute;top:0;left:0;width:100%;height:60px;background-color:var(--bg-cards);z-index:25;margin:0;padding:0 20px;box-sizing:border-box;}
.search-flex-container{display:flex;justify-content:space-between;align-items:center;position:relative;float:right;width:100%;height:100%;background-color:rgba(0,0,0,0);overflow:hidden;margin:0;animation:animateSearch .20s ease}
.search-flex-container .search-form{position:relative;height:34px;background-color:rgb(139 139 139 / 0.16);flex:1;padding: 0 0 0 10px;border:0;border-radius: 4px 0 0 4px;}
.search-flex-container .search-input{position:relative;width:100%;height:35px;background-color:rgba(0,0,0,0);font-size:14px;color:var(--search-bt-text);font-weight:400;padding:0 15px 0 0;border:0;}
.search-flex-container .search-input:focus,.search-flex-container .search-input::placeholder{color:var(--search-bt-text);outline:none}
.search-flex-container .search-input:focus,.search-flex-container .search-input::placeholder{color:var(--search-bt-text);outline:none}
.search-flex-container .search-input::placeholder{opacity:.70}
.search-hidden:after{content:'\f00d';font-family:'Font Awesome 6 Free';font-weight:900;margin:0;}
@-webkit-keyframes animateSearch{0%{width:80%;opacity:0}100%{width:100%;opacity:1}}
.search-flex-close{width:34px;height:34px;border-radius:0 4px 4px 0;background:rgb(139 139 139 / 0.16);color:var(--search-bt-text);font-size:14px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:transform ease-out .2s;z-index:20;padding:0;margin:0;}
.search-flex-close:hover{opacity:0.8;}
.search-button-flex{color:var(--button-bg-color);top:0;right:0;width:40px;height:40px;font-size:16px;text-align:center;line-height:40px;cursor:pointer;z-index:20;padding:0;margin:0;transition:margin .25s ease;}
.search-button-flex:before{content:"\f002";font-family:'Font Awesome 6 Free';font-weight:900}
input.search-input{background-color:transparent;border:0;text-align:start;font-size:35px;padding:20px;color:#fff;-webkit-transition:all .3s ease-out;-moz-transition:all .3s ease-out;-ms-transition:all .3s ease-out;-o-transition:all .3s ease-out;transition:all .3s ease-out}
input.search-input[type=text]{width:83%;height:60px;display:block}
.search-msg{text-align:center;font-size:18px;color:rgba(255,255,255,0.96);padding:5px 0;margin:10px 0;border-bottom:1px dashed rgba(255 255 255 / 0.36)}
.search-input{position:relative;padding:20px;padding-bottom:10px}
.search-input input{border-radius:5px;padding:5px 10px;width:98%;border:2px solid #eee}
#cookies-iki{display:none;position:fixed;bottom:20px;left:20px;width:300px;background-color:var(--block-bg);z-index:222;padding:20px;visibility:hidden;opacity:0;border-radius:4px;box-shadow:0 2px 8px 0px rgb(0 0 0 / 0.11);transition:all .30s ease}
#cookies-iki .cookies .widget .widget-content a{color:var(--nav-site-text);text-decoration:underline;}
#cookies-iki .cookies .widget .widget-content a:after{content:'\f08e';font-family:'Font Awesome 6 Free';font-size:11px;font-weight:700;margin:0 0 0 3px;vertical-align:middle;}
#cookies-iki.cookies-show{visibility:visible;opacity:1;}
#cookies-iki .cookies .widget .widget-title{display:none;}
.cookies-bt{display:inline-block;height:35px;background-color:var(--button-bg-color);font-size:14px;color:var(--button-text-color);font-weight:600;line-height:35px;padding:0 20px;border:0;border-radius:4px;}
#cookies-iki .cookies .widget .widget-content{display:block;font-size:14px;color:var(--nav-site-text);margin:0 0 15px;}
.cookies-bt:hover{opacity:0.8}
#hidden-widget-container,.hide,.hidden-widgets{display:none;visibility:hidden}
.post-snip{color:var(--post-snip-data);font-size:12px;font-weight:400;padding:0;display:inline-flex;align-items:center;flex-wrap: wrap;}
.post-author:empty{display:none;}
.post-author{font-weight: 500;margin:0 4px;}
.post-author:not(.entery-category-fly .post-author){color:var(--lables-buttons-color);}
.featured-box .post-snip:not(.featured-block .post-snip),.modal-grid .post-snip,.block-section .post-snip,.sidebar .PopularPosts .gaint .post-snip,.video-section .post-snip,.hall-section .post-snip{--post-snip-data:var(--snip-text-color);--label-text-color:var(--snip-text-color);}
.entery-category-box{overflow:hidden;}
.block-box .entery-category-box, .sidebar .popular-post .entery-category-box{padding: 7px 0 0;}
.post-tag:empty,.post-tag-fly:empty{display:none;}
.post-tag{width:fit-content;display:flex;align-items:center;height:18px;background-color:var(--lables-buttons-color);font-size:10px;color:var(--lables-text-color);font-weight:600;text-transform:uppercase;line-height:0;padding:1px 8px 0;border-radius:2px;z-index:2;}
img.post-author-image{position:relative;display:inline-block;height:20px;width:20px;border-radius:50%;vertical-align:middle;}
.rtl img.post-author-image{margin: 0 0 0 5px;}
.post-author:after{position:relative;display:inline-block;content: '\002D';margin:0 3px;color:var(--post-snip-data)}
.post-inner-username{display:flex;flex-direction:column;margin:0 0 0 10px;}
.rtl .post-inner-username{margin:0 10px 0 0;}
.all-flex{display:flex;justify-content:space-between;align-items:center;padding:0 0 12px;margin: 0 0 15px;border-bottom:1px solid rgb(100 100 100 / 0.12)}
.post-inner-comments.flex{position:relative;overflow:hidden;margin:0 5px 0;display:flex;align-items:center;gap:8px;}
.post-times{position:relative;overflow:hidden;display:inline-flex;gap:5px;}
.post-author-times{position:relative;display:block;font-size:12px;color:var(--theme-text-color);}
.post-author-times i{margin:0 4px 0 0;}
.rtl .post-author-times i{margin:0 0 0 4px;}
.post-times .post-date{position:relative;font-size:12px;color:var(--post-snip-data);}
.post-date{display:inline-flex;align-items:center;gap:4px;}
#readTime{position:relative;display:inline-flex;font-size:12px;color:var(--post-snip-data);align-items:center;gap:2px;}
#readTime:before{content:"\f017";font-family:'Font Awesome 6 Free';font-size:13px;margin:0;}
.post-times .post-date:before{content:"\f272";font-family:'Font Awesome 6 Free';font-size:13px;margin:0;}
.post-snip .post-date:before{font-family:'Font Awesome 6 Free';font-weight:400;margin:0 3px 0 0}
.item .post-snip .post-author:before{content:'By -';margin:0 3px 0 0;font-weight:normal;}
.item .post-snip .post-date:before{content:'\f133'}
.post-snip a{color:#333;transition:color .40s}
.post-snip .author-image{overflow:hidden;position:relative;display:inline-block;width:30px;vertical-align:middle;height:30px;background-color:var(--runs-author-color);margin:0 3px 0 0;border:1px solid rgba(0 0 0 / 0.25);border-radius:100%;box-shadow:0px 0px 4px 3px rgba(0 0 0 / 0.06);}
.t-ads{display:block;overflow: hidden;background-color:var(--ads-bg);text-align:center;line-height:1.5;padding:4vh 15px;font-size:13px;font-family: monospace;font-style:italic;color:var(--ads-text);border-radius:6px;}
.t-ads-res{display:block;background-color:var(--ads-bg);text-align:center;line-height:1.5;font-family: monospace;font-size:13px;padding:10vh 15px;font-style:italic;color:var(--ads-text);border-radius:6px;}
.post-filter .entry-title,.raw-box .entry-title,.flex-blocks .entry-title,.related-wrap-ui .entry-title,.Super-related .entry-title{display:block;width:100%;text-decoration:none;font-weight:700;line-height:1.3;padding:5px 0;margin:0}
.post-filter .entry-title, .raw-box .modal-grid  .entery-category-box .entry-title,.raw-box .entery-category .entry-title{font-size:17px;}
.raw-box .entery-category .entry-title{margin:10px 0;}
.raw-box .entery-category-box .entry-title{font-size:15px;line-height: 19px;}
.Super-related .entry-title,.flex-blocks .entry-title,.related-wrap-ui .entry-title{font-size:14px;}
.entry-title a{display:block;color:var(--featured-posts-title)}
.entry-title a:hover{opacity:0.8}
.StickyBox{position:fixed;top:0;right:0;bottom:0;left:0;width:100%;height:100%;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transform: translate3d(0,72%,0);transition: all .2s ease;z-index:15151515;}
.show-share .StickyBox{opacity:1;visibility:visible;transform: translate3d(0,0,0);}
.StickyTab{display:flex;flex-direction:row;align-content:center;justify-content:space-between;align-items:center;width:100%;box-sizing:border-box;padding:0 0 20px;margin:0 0 10px;color:var(--title-share);border-bottom:1px solid rgb(92 92 92 / 0.17);}
.StickyType{position:relative;display:block;float:left;font-size:15px;font-weight: 700;}
.copy-section{width:100%;}
.copy-section .title{font-size:14px;font-weight:700;padding:0 20px;}
.copy-post{display:flex;align-items:center;align-content:center;box-sizing:border-box;position:relative;justify-content:center;margin:10px 20px 0;}
.copy-post:before{content:'\f0c1';font-weight:600;font-family:'Font Awesome 6 Free';position:absolute;left:12px;font-size:15px;color:var(--theme-text-color)}
.rtl .copy-post:before{left:initial;right:12px;}
.copy-post.copied:before{content:'\f560';color:#16c900;}
.copy-post input#showlink{color:#6b6b6b;background: transparent;width:100%;height:35px;padding:0 0 0 38px;border:1px solid rgb(133 133 133 / 0.20);border-radius:5px 0 0 5px;}
.rtl .copy-post input#showlink{padding:0 38px 0 0;border-radius:0 5px 5px 0;}
.copy-post button{background:var(--button-bg-color);color:var(--button-text-color);height:35px;width:80px;border:none;cursor:pointer;border-radius:0 5px 5px 0;}
.rtl .copy-post button{border-radius:5px 0 0 5px;}
.StickyTab label{position:relative;display:block;font-size:20px;cursor:pointer;color:var(--title-share)}
.StickyDemo{width:100%;max-width:500px;max-height:90%;display:flex;margin:0 auto;padding:20px 20px 35px;background-color:var(--bg-cards);border-radius:8px;overflow:hidden;position:relative;box-shadow:0 10px 8px -8px rgb(0 0 0 / 0.12);flex-direction:column;align-content:center;align-items:center;justify-content:space-between;}
.share-wrapper-icons.kcode-icon{display:flex;flex-wrap:wrap;list-style:none;margin:0 0 10px;padding:10px 0 20px;border-bottom:1px solid rgb(133 133 133 / 0.20);}
.share-wrapper-icons.kcode-icon li{list-style:none;width:25%;text-align:center;}
.share-wrapper-icons.kcode-icon li a{display:block;width:80px;height:40px;line-height:25px;font-size:11px;margin:6px auto;padding:15px 0;border-radius:2px;background:var(--box-posts-share);border:1px solid rgb(205 222 247 / 0.18);text-align:center;cursor:pointer;}
.share-wrapper-icons.kcode-icon li a:hover{opacity:0.8}
.messageDone span{position:absolute;left:0;right:0;bottom:-70px;font-size:12px;display:block;width:190px;margin:0 auto 20px;padding:8px;border-radius:3px;background-color:rgb(0 0 0 / 0.63);color:#fefefe;line-height:20px;text-align:center;opacity:0;-webkit-animation:slidein 2s ease forwards;animation:slidein 2s ease forwards;}
div#messageDone{display:block;padding:20px 0 0;}
.share-wrapper-icons.kcode-icon a:before{font-size:24px;text-align:center;margin:0 auto;display:block;}
.show-share .overlay{filter:blur(2.5px);background-color:rgba(27,27,37,0.5);z-index:151515;backdrop-filter:saturate(100%) blur(2.5px);visibility:visible;opacity:1;}
.featured-box.item0 .entry-title,.sidebar .PopularPosts .gaint h2.entry-title,.modal-grid .entry-title a,.block-section.item0 .entry-title a,.video-section.item0 .entry-title a,.post-filter .entry-title,.hall-section.item0 .entry-title a{color:var(--featured-posts-title-featured)}
.block-section.item0 .entry-title,.hall-section.item0 .entry-title,.video-section.item0 .entry-title{font-size:23px;}
.t-main-hero{display:flex;flex-wrap:wrap;justify-content:space-between;}
a.more-c:hover{opacity:0.8}
.raw-main-wrapper{display:grid;grid-template-columns:repeat(7,1fr);grid-gap:12px;width:100%;}
.block-section.fl.item0{grid-column:1/5;}
.block-box.fl{display:flex;flex-direction:column;grid-column:5/8;background:var(--bg-cards);box-shadow:var(--shadow-light);border:none;border-radius:8px;overflow:hidden;}
.modal-grid{width:calc((100% - 45px) / 4);position:relative;margin:0;background: var(--bg-cards);overflow: hidden;border-radius: 4px;box-shadow: var(--shadow-light);}
.t-hero .modal-image .post-filter-link{position:relative;width:100%;height:130px;display:block;overflow:hidden}
.modal-grid .modal-image .post-filter-inner{position:relative;width:100%;height:274px;display:block;overflow:hidden}
.modal-grid .entry-title{font-size: 18px;}
.block-section .block-img{position:relative;float:left;width:100%;aspect-ratio:16/9;overflow:hidden;box-sizing:border-box;border-radius:8px;padding:0;margin:0;box-shadow:var(--shadow-light);}
.block-section .block-img img.snip-thumbnail{width:100%;height:100%;object-fit:cover;display:block;border-radius:8px;}
.block-section .block-img .entery-category-fly{position:absolute;left:0;bottom:0;z-index:11;width:100%;box-sizing:border-box;padding:12px 16px 14px 16px;background:linear-gradient(to top, rgba(4,12,62,0.95) 0%, rgba(4,12,62,0.65) 60%, transparent 100%);}
.block-section.item0 .entry-title,.block-section.item0 .entry-title a{color:#ffffff;font-size:20px;font-weight:700;line-height:1.4;text-shadow:0 2px 6px rgba(0,0,0,0.9);}
.block-section .entery-category-fly .post-snip,.block-section .entery-category-fly .post-snip *,.block-section .entery-category-fly .post-author,.block-section .entery-category-fly .post-date{color:rgba(255,255,255,0.92);text-shadow:0 1px 4px rgba(0,0,0,0.85);font-size:13px;}
.block-step{position:relative;display:flex;align-items:center;padding:10px 14px;overflow:hidden;border-bottom:1px solid #f1f5f9;box-sizing:border-box;width:100%;}
.block-step:last-child{border-bottom:none;}
.block-step .entery-category-box{flex:1;min-width:0;}
.block-step .entery-category-box .entry-title{font-size:15px;font-weight:700;line-height:1.4;margin:0 0 4px 0;}
.block-step .entery-category-box .entry-title a{color:var(--theme-text-color, #1a1a1a);text-decoration:none;}
.block-step .entery-category-box .entry-title a:hover{color:var(--button-bg-color, #2563eb);}
.block-step .entery-category-box .post-snip{color:#64748b;font-size:12.5px;}
