<!--htbd design-->
    .htbd-post-wrapper { line-height: 1.8; color: #212121; }
    .htbd-post-wrapper h2 { color: #1a73e8; font-size: 24px; border-bottom: 2px solid #e0e0e0; padding-bottom: 8px; margin-top: 30px; margin-bottom: 20px; font-weight: bold; text-align: center; }
    .htbd-post-wrapper h3 { color: #37474f; font-size: 20px; font-weight: 700; margin-top: 25px; margin-bottom: 12px; border-left: 4px solid #1a73e8; padding-left: 10px; text-align: justify; }
    .htbd-post-wrapper h4 { color: #455a64; font-size: 19px; font-weight: 600; margin-top: 20px; margin-bottom: 10px; }
    .htbd-post-wrapper p { font-size: 18px; text-align: justify; margin-bottom: 18px; }
    .htbd-badge { background-color: #e8f0fe; color: #1967d2; padding: 8px 15px; border-radius: 20px; font-size: 16px; font-weight: 600; display: inline-block; margin-bottom: 20px; border: 1px solid #d2e3fc; }
    .htbd-qbox { background-color: #f1f8ff; border: 1px solid #cce5ff; padding: 15px; border-radius: 5px; margin-bottom: 25px; color: #004085; }
    .htbd-qbox p { margin-bottom: 0; }

    .htbd-link-box { background-color: #ffffff; border: 2px solid #e0e0e0; border-radius: 8px; padding: 20px; margin: 30px 0; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }
    .htbd-link-box h4 { margin: 0 0 15px 0; color: #d32f2f; font-size: 19px; font-weight: bold; }
    .htbd-link-box ul { margin: 0; padding-left: 0; list-style: none; }
    .htbd-link-box li { margin-bottom: 12px; padding-left: 25px; position: relative; font-size: 18px; }
    .htbd-link-box li::before { content: "\00BB"; position: absolute; left: 0; color: #1a73e8; font-size: 18px; top: 4px; font-weight: bold; }
    .htbd-link-box a { color: #1a73e8; text-decoration: none; font-weight: 600; }
    .htbd-link-box a:hover { color: #0d47a1; text-decoration: underline; }

    .htbd-post-wrapper ul:not(.htbd-link-box ul, .htbd-exam-tips ul) { margin-bottom: 20px; padding-left: 20px; }
    .htbd-post-wrapper ul:not(.htbd-link-box ul, .htbd-exam-tips ul) li { margin-bottom: 8px; font-size: 18px; list-style-type: square; }
    .htbd-post-wrapper blockquote { font-style: italic; background: #f9f9f9; border-left: 5px solid #607d8b; margin: 20px 0; padding: 15px 20px; font-size: 18px; color: #555; }

    /* Exam Tips (CSS for Normal HTML Structure) */
    .htbd-post-wrapper > div:nth-last-of-type(4) { 
        background: #e8f5e9; padding: 20px; border-radius: 8px; border: 1px solid #c8e6c9; margin-top: 30px; margin-bottom: 30px; 
    }

    .htbd-post-wrapper > div > h3 { 
        text-align: center; color: #2e7d32; margin-bottom: 15px; border-bottom: 2px dashed #a5d6a7; padding-bottom: 10px; border-left: none; display: flex; align-items: center; justify-content: center; gap: 10px; 
    }
    .htbd-post-wrapper > div > ul { list-style: none; padding-left: 0; }
    .htbd-post-wrapper > div > ul > li { margin-bottom: 10px; font-size: 17px; display: flex; align-items: flex-start; gap: 10px; }

    /* FAQ Section Styles */
    .htbd-faq-wrap { background: #fff3e0; padding: 20px; border-radius: 8px; border: 1px solid #ffe0b2; margin-top: 30px; margin-bottom: 30px; }
    .htbd-faq-wrap h3 { text-align: center; color: #e65100; margin-bottom: 20px; border-bottom: 2px dashed #ffe0b2; padding-bottom: 10px; border-left: none; }
    .htbd-faq-item { margin-bottom: 15px; }
    .htbd-faq-q { font-weight: bold; color: #bf360c; margin-bottom: 5px; display: flex; align-items: center; gap: 8px; }
    .htbd-faq-a { background: #fff; padding: 10px; border-radius: 5px; border-left: 3px solid #ff9800; font-size: 17px; display: flex; align-items: flex-start; gap: 8px; }

    /* Icons */
    .htbd-icon { width: 24px; height: 24px; flex-shrink: 0; }
    .htbd-icon-sm { width: 18px; height: 18px; flex-shrink: 0; margin-top: 4px; }

    .htbd-eng-sec { background-color: #fafafa; padding: 20px 15px; border-top: 3px solid #4caf50; margin-top: 40px; }
    @media (max-width: 600px) {
        .htbd-post-wrapper h2 { font-size: 22px; }
        .htbd-post-wrapper h3 { font-size: 19px; }
        .htbd-post-wrapper p, .htbd-post-wrapper li { font-size: 17px; }
    }

    /* Specific Fix for Exam Tips targeting without class */
    .htbd-post-wrapper > div > h3:has(svg) {
         text-align: center; color: #2e7d32; border-bottom: 2px dashed #a5d6a7;
    }








/* ==========================================================================
   HelpTrickBD SolaimanLipi Global Typography & Layout Engine (b:skin Native)
   ========================================================================== */
@font-face {
    font-family: 'SolaimanLipi';
    font-display: swap;
    font-style: normal;
    font-weight: 400;
    src: url('https://fonts.maateen.me/solaiman-lipi/solaimanlipi-normal-v1.0.woff2') format('woff2');
  }
  @font-face {
    font-family: 'SolaimanLipi';
    font-display: swap;
    font-style: normal;
    font-weight: 700;
    src: url('https://fonts.maateen.me/solaiman-lipi/solaimanlipi-bold-v1.0.woff2') format('woff2');
  }

  /* 1. Apply SolaimanLipi Font Family Sitewide */
  html, body, 
  .post-body, 
  .post-title, 
  .post-title a,
  h1, h2, h3, h4, h5, h6, 
  p, span, a, li, td, th, 
