  /* 16. Reading Progress Bar & Image Captions */
  .dark #ht-reading-progress-container,
  body.dark #ht-reading-progress-container,
  #mainContent.dark #ht-reading-progress-container {
    background: rgba(30, 41, 59, 0.7) !important;
  }
  .dark .post-body figcaption,
  .dark .post-body span[style*="font-style: italic"],
  #mainContent.dark .post-body figcaption {
    color: #94a3b8 !important;
  }

  /* 3. Featured Image Overlay Titles & Metadata (Crisp White on Dark Cards) */
  .entery-category-fly,
  .entery-category-fly .entry-title,
  .entery-category-fly .entry-title a,
  .entery-category-fly .post-snip,
  .entery-category-fly .post-snip *,
  .entery-category-fly .post-author,
  .entery-category-fly .post-date,
  .block-section.item0 .entry-title,
  .block-section.item0 .entry-title a,
  .hall-section.item0 .entry-title,
  .hall-section.item0 .entry-title a,
  .featured-box.item0 .entry-title,
  .featured-box.item0 .entry-title a,
  .video-section.item0 .entry-title,
  .video-section.item0 .entry-title a,
  .modal-grid .entry-title,
  .modal-grid .entry-title a,
  .sidebar .PopularPosts .gaint h2.entry-title,
  .sidebar .PopularPosts .gaint h2.entry-title a {
    color: #ffffff !important;
    text-shadow: 0 2px 6px rgba(0, 0, 0, 0.9) !important;
  }

  .block-section.item0 .entry-title,
  .block-section.item0 .entry-title a,
  .hall-section.item0 .entry-title,
  .hall-section.item0 .entry-title a,
  .video-section.item0 .entry-title,
  .video-section.item0 .entry-title a,
  .featured-box.item0 .entry-title,
  .featured-box.item0 .entry-title a {
    font-size: 22px !important;
    font-weight: 700 !important;
    line-height: 1.4 !important;
  }

  .entery-category-fly .post-author,
  .entery-category-fly .post-date,
  .entery-category-fly .post-snip {
    color: rgba(255, 255, 255, 0.92) !important;
    font-size: 13px !important;
    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.85) !important;
  }

  /* 4. Bold and Sharp Popular Posts in Sidebar */
  .sidebar .PopularPosts .entry-title,
  .sidebar .PopularPosts .entry-title a,
  .sidebarui-posts .entry-title,
  .sidebarui-posts .entry-title a {
    font-size: 14.5px !important;
    font-weight: 700 !important;
    line-height: 1.4 !important;
  }

  /* 5. Category Badges */
  .entery-category a,
  .post-filter .entery-category a,
  .sidebar .PopularPosts .entery-category a {
    font-weight: 700 !important;
    font-size: 11.5px !important;
    letter-spacing: 0.5px;
  }

  /* 6. Post Body Typography, Lists & Readability */
  .post-body p,
  .entry-content p {
    font-size: 18px !important;
    line-height: 1.85 !important;
    color: #202124 !important;
    margin-bottom: 18px !important;
  }

  .post-body ol, 
  .post-body ul,
  .entry-content ol,
  .entry-content ul {
    margin: 18px 0 24px 0 !important;
    padding-left: 28px !important;
  }

  .post-body ol li, 
  .post-body ul li,
  .entry-content ol li,
  .entry-content ul li {
    font-size: 17.5px !important;
    line-height: 1.85 !important;
    color: #24292f !important;
    margin-bottom: 14px !important;
    padding-bottom: 4px !important;
  }

  /* Distinct Question & Answer spacing inside lists */
  .post-body ol li strong,
  .post-body ul li strong,
  .entry-content ol li strong,
  .entry-content ul li strong {
    display: inline-block !important;
    margin-bottom: 5px !important;
    color: #0f172a !important;
    font-size: 18px !important;
  }

  .post-body ol li em,
  .post-body ul li em,
  .entry-content ol li em,
  .entry-content ul li em {
    font-style: normal !important;
    color: #0369a1 !important;
    font-weight: 600 !important;
  }

  /* 7. Table Responsive & Mobile Overflow Protection */
  .table-responsive {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    margin: 15px 0;
  }
  .post-body table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid rgba(154, 154, 154, 0.18);
    margin: 0;
  }
  @media screen and (max-width: 768px) {
    .post-body table {
      display: block;
      width: 100%;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }
  }

  /* 8. FontAwesome Font-Display Swap Override */
  @font-face {
    font-family: 'Font Awesome 6 Free';
    font-display: swap;
  }
  @font-face {
    font-family: 'Font Awesome 6 Brands';
    font-display: swap;
  }

  /* 9. Header Logo Responsive Dimensions */
  #darkroom1 {
    max-height: 42px;
    width: auto;
    object-fit: contain;
  }
  @media screen and (max-width: 768px) {
    #darkroom1 {
      max-width: 105px !important;
      height: auto !important;
    }
  }

  /* 10. Image Cumulative Layout Shift (CLS) Prevention */
  .post-body img {
    max-width: 100% !important;
    height: auto !important;
    display: block;
    margin: 12px auto;
    border-radius: 6px;
    box-sizing: border-box;
  }
  .post-body .separator, 
  .post-body .separator a {
    max-width: 100% !important;
    display: block !important;
    margin-left: auto !important;
    margin-right: auto !important;
    text-align: center !important;
  }
  .post-body figure {
    margin: 15px auto;
    max-width: 100%;
    text-align: center;
  }
  .post-body figcaption {
    font-size: 13.5px;
    color: var(--theme-text-color, #555555);
    text-align: center;
    margin-top: 6px;
    font-style: italic;
  }

  /* 11. Homepage Hero LCP Thumbnail Visibility Permanent Fix */
  .snip-thumbnail.lcp-hero-thumb,
  img.lcp-hero-thumb,
  .snip-thumbnail[loading='eager'],
  .snip-thumbnail[fetchpriority='high'],
  .post-filter.post-0 .snip-thumbnail {
    opacity: 1 !important;
  }

b:if.b:template-skin:
html,body#layout #outer-wrapper,body#layout .outer-container{width:auto;padding:0;}
body#layout{position:relative;width:auto;max-width:100%;background:#ffffff;padding:95px 5px 0;margin:1px;border:1px solid #def2ff;}
body#layout:before{content:"FlexSpot 2.7.0.V";font-family:MONOSPACE;position:absolute;top:20px;right:20px;z-index:1;padding:6px 14px;font-size:15px;border-radius:10px;font-weight:400;color:#919191;background:#fdfdfd;border:1px solid #cac9c9 !important;}
body#layout div.section{display:block;border-radius:5px;background-color:#f3f3f3!important;margin:0 5px 10px!important;padding:16px 16px 18px!important;border-color:#009bde;border:0;}
body#layout .section h4{font-size:14px;margin:0;!important;}
body#layout .section h4,body#layout div.layout-title{display:-webkit-box}
body#layout .section h4:after{text-transform:initial;color:#6b6b6b;font-weight:400}
body#layout .widget-content{border-radius:5px;width:auto;max-width:none;max-height:none;margin:0;border:1px solid #538bf5;}
body#layout .widget .widget-content a.editlink{border-radius:2px}
body#layout .visibility .editlink{background:#3363ff url(https://1.bp.blogspot.com/-yggSg-F-GrY/YJbChcKAXNI/AAAAAAAABmk/hn1KE7b_qtEeu4EYEDnejdq17f0xZjz4QCLcBGAsYHQ/s20-rw/) no-repeat center !important;}
body#layout .visibility .editlink:hover{background-color:#bed8ff !important}
body#layout .draggable-widget .widget-wrap2 .widget-content{border-radius:0 5px 5px 0;}
body#layout .draggable-widget .widget-wrap2{border-radius:5px;background:#3363ff url(https://1.bp.blogspot.com/-hMi3I2lPKLQ/XcVHiWtl6GI/AAAAAAAAAPQ/M2XKqrvMItIH7dQdiEyH9cQ35lvkW36FgCNcBGAsYHQ/s1600-rw/) no-repeat 4px 50%!important}
body#layout .draggable-widget .widget-wrap1 .widget-wrap2{background-color:#3363ff!important}
body#layout .visibility .layout-widget-state.visible{background-image:url(https://1.bp.blogspot.com/-uYbp0hXEKwo/XcVGwr7W7-I/AAAAAAAAAPI/lihmCldvuy0c0J54DHpqaZnQ9sZ-qv4zgCNcBGAsYHQ/s1600-rw/)!important}
body#layout .visibility .layout-widget-state.not-visible{background-image:url(https://1.bp.blogspot.com/-zsoXuAqK0Rs/YSrwXcPcFOI/AAAAAAAACHU/kJA24Ue423YlPX2svO7hSJEGNMcdcn-eACLcBGAsYHQ/s48-rw/)!important;background-size:24px!important;background-repeat:no-repeat;opacity:1;}
body#layout .add_widget a{display:flex;color:#4385f5!important;!important;}
body#layout div.admin-section{background-color:rgba(53 255 49/0.25) !important;overflow:hidden!important;border-color:#bcbcbc}
body#layout .layout-widget-description{display:none}
body#layout .admin-area,body#layout #main-menu .widget{display:block!important;width:100%;}
body#layout .admin-area .widget-wrap1{margin:0 10px;}
body#layout .admin-section .widget{float:left;width:50% !important;}
nav#top-bar .container div#header-room{overflow:hidden;}
nav#top-bar .container div#header-room div#LinkList5{margin:8px 0 0 1%;}
nav#top-bar .container .header-room .widget{width:49%;float:left;}
body#layout #custom-ads-placeholder{display:flex!important}
body#layout #custom-ads-placeholder .section{width:49%}
body#layout .row{display:flex}
body#layout div#promo-ok > h4:after{content:' - Put ad code to show ads inside posts/pages'}
body#layout .show-menu-space,body#layout .search-toggle,body#layout #nav-search{display:none}
body#layout .header-section{width: 100%;}
body#layout .header-left{display:flex;}
body#layout #header-room1,.Super-FlexMenu{width:50%;}
body#layout #mega-wrap .widget, .rtl body#layout .add_widget a{display:block}
body#layout .search-toggle,body#layout .section-sticky{display:none}
body#layout #mega-wrap .widget{display:block}
body#layout #center-container{margin:0}
body#layout #center-container>.container{display:flex;margin:auto}
body#layout #feed-view{width:68.66%;padding:0}
body#layout #sidebar-container{width:33.33%;padding:0;display:block}
body#layout .sidebar .widget,body#layout .sidebar .widget-content{float:none;overflow:visible}
body#layout .fl-footer, body#layout .footer-outer{display:flex;}
body#layout .Footer-Function, body#layout div#footer-checks-menu,body#layout div#footer-copyright{overflow:hidden!important;width:100%}
body#layout .Footer-adv{overflow:hidden !important;}
body#layout .Footer-adv div.widget{float:left !important;width:49% !important;}
body#layout div#LinkList7{margin-left:1% !important;}
body#layout .section > h4:after{font-size:12px;font-size:12px;font-weight:400;}
body#layout #admin > h4:after{content:' - For setting up comments system, related posts, dark mode and button texts.'}
body#layout #header-room > h4:after{content:' - Set Desktop Logo here with Dark Logo (use link box for dark logo)'}
body#layout #header-room1 > h4:after{content:' - Set Mobile Logo here with Dark Logo (use link box for dark logo)'}
body#layout #Super-FlexMenu > h4:after{content:' - Edit menu and submenu links here'}
body#layout #hot-posts > h4:after{content:' - Trending/Popular Section'}
body#layout #room-box > h4:after{content:' - Main Featured Posts Section(A)'}
body#layout #room-box1 > h4:after{content:' - Bottom Featured Posts Section(A)'}
body#layout #room-box2 > h4:after{content:' - Bottom Featured Posts Section(B)'}
body#layout #ft-post > h4:after{content:' - Feature and Popular Posts both Gadgets'}
body#layout #main-ads1 > h4:after{content:' - Ads Section place ad code here'}
body#layout #room-box0 > h4:after{content:' - Featured Post Section'}
body#layout #main > h4:after{content:' - Recent Posts,Comments,no. of Posts etc.'}
body#layout #upper-ad > h4:after{content:' - Only Turn On/Off this widget'}
body#layout #lower-ad > h4:after{content:' - Only Turn On/Off this widget'}
body#layout #main-ads-below > h4:after{content:' - Below recent Posts ads section (responsive)'}
body#layout #main-ads2 > h4:after{content:' - Bottom Footer Ads Section (responsive)'}
body#layout #Footer-Function3 > h4:after{content:' - Change footer logo and caption'}
body#layout .Footer-Function > h4:after{content:' - Use this Section for footer widgets '}
body#layout #footer-checks-menu > h4:after{content:' - Footer Pages Links'}
body#layout #footer-copyright > h4:after{content:' - Footer Copyright Link'}
body#layout #sidebar > h4:after{content:' - Sidebar widgets'}
body#layout #cookies > h4:after{content:' - Change Cookies Consent from here'}

